class Collectible {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }

  getDescription() {
    return "A Collectible named " + this.name + " worth " + this.value + " points.";
  }
}

class Gemstone extends Collectible {
  constructor(name, value, rarity) {
    super(name, value);
    this.rarity = rarity;
  }

  getDescription() {
    return "A " + this.rarity + " Gemstone named " + this.name + " worth " + this.value + " points.";
  }

  polish() {
    return "The " + this.name + " gemstone is now sparkling!";
  }
}

